// TH14 v1.00b Extra boss attack 1 (non-spell) Boss1; source st07bs.ecl.txt:113-133.
// Closure: Boss1_at 176-206 (firing). default.ecl EffChargePoint2 176-186 is pure anm (omitted).
// Entry state from task: HP 12100, center (0,128), hurt/hit 48x48 -> r=24,
//   moveLimit(0,128,280,64) -> per-tick clamp x[-140,140], y[96,160].
// Self slots: int0 = moveRand step count, fx0/fx1 = logical move direction.

const TIME_LIMIT: int = 3424;  // 120 opening + 3000 slot-0 timer + 300 tail + 4 startup
const OPENING_BUFFER: int = 120;

// Boss1_at base angle A starts at RANDRAD and advances by +-3.883222 rad.
// 3.883222 rad = 40503.47 BAM; the 0.032724924 rad layer spread is exactly 1024/3 BAM.
// Accumulate in 1/48 BAM so three spread steps land on exactly 1024 BAM.
const AT_STEP_48: int = 1944167;    // 3.883222 rad in 1/48 BAM
const AT_SPREAD_48: int = 16384;    // 0.032724924 rad in 1/48 BAM

// ---------------------------------------------------------------------------
// Boss1_at (source 176-206): one fixed alternating-layer ring volley.
// etAim 0,10: layer q angle = alpha + (-1)^q * (R(i) + H(7,q)*1deg),
// H = 0,1,1,2,2,3,3; layer speed index k = 0,2,2,4,4,6,6 over s0=3, s1=2.5.
// Negating R(i) only permutes the 14-way ring, so each layer keeps the same
// point set as the source (creation order stays layer-outer, path-inner).
// ---------------------------------------------------------------------------
sub fire_layer(base48: int, speed: fx) {
    sh_angle(0, (base48 / 48) as angle, 0deg);
    sh_speed(0, speed, 0fx);
    // etDist(0,16) plus the ANIM a=1 spawn retreat position -= 4*velocity.
    sh_dist(0, 16fx - 4fx * speed);
    sh_fire(0);
}

sub at_burst(acc48: int) {
    fire_layer(acc48, 3fx);                            // q0: H 0,  speed 3
    fire_layer(acc48 - AT_SPREAD_48, 2.833333fx);      // q1: H-1,  speed 2.8333
    fire_layer(acc48 + AT_SPREAD_48, 2.833333fx);      // q2: H+1,  speed 2.8333
    fire_layer(acc48 - 2 * AT_SPREAD_48, 2.666667fx);  // q3: H-2,  speed 2.6667
    fire_layer(acc48 + 2 * AT_SPREAD_48, 2.666667fx);  // q4: H+2,  speed 2.6667
    fire_layer(acc48 - 3 * AT_SPREAD_48, 2.5fx);       // q5: H-3,  speed 2.5
    fire_layer(acc48 + 3 * AT_SPREAD_48, 2.5fx);       // q6: H+3,  speed 2.5
}

async sub boss_at() {
    sh_reset(0);
    sh_sprite(0, TH14_RICE, 4);   // etSprite(0, 8, 4): type 8 rice, color 4
    sh_ring(0, 1);
    sh_count(0, 14, 1);           // 14 ways; layers are fired one by one below
    sh_offset(0, 0fx, 24fx);      // etOffset(0, 0, 24)
    // $C=10000 outer steps, $D=8 volleys, 17 frames apart, $B negated each group.
    // The slot-0 3000-frame timer cuts the run after 169 volleys
    // (21 full groups of 8 plus one): 141 + 17*168 < 3000 < 141 + 17*169.
    var acc: int = rand(65536) * 48;   // %A = %RANDRAD over the full circle
    var sign: int = 1;
    for g in 0..22 {
        var n: int = 8;
        if g == 21 { n = 1; }
        for k in 0..n {
            at_burst(acc);
            acc = acc + sign * AT_STEP_48;
            wait(17);
        }
        sign = 0 - sign;
    }
}

// ---------------------------------------------------------------------------
// moveRand(60, 4, 1.0) with this card's limits (TH16 movement recipe):
// speed 1 -> 0 linearly over 60 steps, direction drawn once, per-frame clamp.
// Source inner direction region is center +- width/4: x +-70, y 112..144.
// ---------------------------------------------------------------------------
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_rand() {
    // Source signed unit random * pi, unwrapped BAM int.
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05 rad = 522 BAM.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_next_step();
}

// Every wait inside the attack advances one source movement tick.
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

async sub boss_body() {
    set_invuln(65535);
    set_hitbox(24fx);    // Boss 27-28 setHurtbox/setHitbox(48,48)
    set_hurtbox(24fx);
    // Source 115-119: timerReset, stars(9) (ordinary reward, omitted), slot-0 interrupt, wait(60).
    wait(60);
    // Source 120-124: EffChargePoint2 and anmPlay/playSound/anmSelect are pure anm/audio.
    wait(80);
    spawn boss_at();     // Source 125: @Boss1_at() async.
    // Source 126-131: loop { wait(120); moveRand(60, 4, 1.0); }
    // Firing stops at the slot-0 timeout (source frame 3000); this body loop only
    // keeps the idle movement running through the tail. BossCard1 is not executed.
    loop {
        card_wait(120);
        move_rand();
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 12100, 0, 0, 0, boss_body);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
